package com.mamtrex.hospital.insurance;
import com.mamtrex.hospital.shared.BaseEntity; import jakarta.persistence.*;
@Entity @Table(name="insurance_claims") public class InsuranceClaim extends BaseEntity { private String patientId; private String payer; private String policyNumber; private String claimNumber; private String status; protected InsuranceClaim(){} public InsuranceClaim(String patientId, String payer, String policyNumber, String claimNumber, String status){this.patientId=patientId; this.payer=payer; this.policyNumber=policyNumber; this.claimNumber=claimNumber; this.status=status;} public String getPatientId(){return patientId;} public String getPayer(){return payer;} public String getPolicyNumber(){return policyNumber;} public String getClaimNumber(){return claimNumber;} public String getStatus(){return status;} }
